<template>
    <div class="main-content">
        <ElForm
            ref="searchFormRef"
            :model="searchForm"
            inline
            class="search-form"
            label-width="68px"
            label-position="left">

                <ElFormItem label="任务名称" prop="task">
                    <el-select v-model="searchForm.task" placeholder="请选择任务" >
                        <el-option
                        v-for="task in taskOpsList"
                        :key="task.id"
                        :label="task.name"
                        :value="task.id"
                        >

                        </el-option>
                    </el-select>

                </ElFormItem>

                <el-form-item label="查询方式" >
                    <el-radio-group v-model="searchType" @change="changeSearchType">
                        <el-radio
                            :label="1">
                            地图查询
                        </el-radio>
                        <el-radio
                            :label="2">
                            车牌号查询
                        </el-radio>

                    </el-radio-group>
                </el-form-item>
                <ElFormItem label="车牌号" prop="carNumber">
                    <el-input :disabled="searchType !== 2" v-model="searchForm.carNumber" placeholder="请输入车牌号" clearable />

                </ElFormItem>

                <ElFormItem>
                    <ElButton
                        color="#4371EE"
                        @click="handleOnsearch"
                    >
                    查询
                    </ElButton>
                </ElFormItem>




        </ElForm>
        <section class="tips" v-show="tips">
            <el-icon><Bell /></el-icon> {{tips}}
        </section>
        <section id="mapParentContainer" class="my-map-container" style="height: 600px;">

            <MyMap @init="initMap" @resize="handleMapResize">
                <section class="map-info-card" v-show="searchType!== 2">
                    <el-card header="操作"  >

                        <el-form-item >
                            <el-radio-group v-model="carType" >
                                <el-radio
                                    v-for="item in radioOps"
                                    :key="item.value"
                                    :label="item.value">
                                    {{ item.label }}
                                </el-radio>

                            </el-radio-group>
                        </el-form-item>
                        <section class="btns">
                            <el-button type="primary" :icon="EditPen" plain @click="startDraw">{{finalCircle ? '重新' : '开始'}}绘制</el-button>
                            <el-button type="primary" :icon="Search"  @click="getCircleMarker">查询</el-button>

                        </section>
                    </el-card>
                    <el-card header="绘制信息"  >
                        <el-form label-position="left" label-width="90px"  >

                            <el-form-item label="圆心经纬度:">
                                <span v-if="circleInfo.center">{{ circleInfo.center[0] }},{{ circleInfo.center[1] }}</span>
                            </el-form-item>
                            <el-form-item label="圆心半径:">
                                <span v-if="circleInfo.radius">{{ circleInfo.radius }}米</span>
                            </el-form-item>
                        </el-form>
                    </el-card>
                </section>
            </MyMap>

        </section>

        <el-card header="待选车辆">
            <el-table
                border
                id="userTable"
                class="table"
                :scrollbar-always-on="true"
                :data="points"
                :max-height="500"
                @row-click ="handleRowClick"
                >
                <el-table-column prop="id" label="id"  />
                <el-table-column prop="carNumber"  label="车牌"  />
                <ElTableColumn prop="endPointLat" label="经纬度">
                    <template #default="scope">
                        <span>
                            经度:{{ scope.row.lng }}<br />
                            纬度:{{ scope.row.lat }}
                        </span>

                    </template>
                </ElTableColumn>
                <ElTableColumn prop="endPointLat" label="操作">
                    <template #default="scope">
                        <el-button type="primary" @click.stop="handleBindTask(scope.row)">绑定任务</el-button>
                    </template>
                </ElTableColumn>
            </el-table>

        </el-card>


    </div>
</template>

<script setup lang="ts">
import useTableSetting from '@/hooks/useTableSetting';
import { ref, onMounted, reactive, nextTick, watch } from 'vue';
import { DictType, dictType } from '@/components/DictSelect/localDictDefine';
import { ElMessage, ElTree, FormInstance, ElMessageBox } from 'element-plus';

import { getFlatDeepTreeData } from '@/utils/common';
import { Search, Plus, EditPen, Bell } from '@element-plus/icons-vue';
import { validateForm } from '@/helper/index';
import MyMap from '@/components/MyMap/index.vue';
import { addDict, delDict, dictList, editDict } from '@/api/index.ts';
import { taskList, paginate, getMarker, searchMarker } from './mock.ts'
import { Circle } from 'vant';

const treeRef = ref<InstanceType<typeof ElTree>>();
const tableData: any = ref([]);
const taskOpsList = ref<object[]>([])

const searchForm = reactive({
    carNumber: '',
    task:'',
});

const searchType = ref(1);   // 默认按地图查询

// 获取任务列表
const getTaskList = async() => {
    // TODO 接口替换，获取所有任务
    const task = await taskList();
    taskOpsList.value = task;
}

const handleMapResize = ({ height }) => {
    const mapParentContainer = document.getElementById('mapParentContainer');
   mapParentContainer.style.height = height +'px'
}

const carType = ref<number>(2); // 默认自有车

const radioOps = ref([
    { label: '全量车', value : 1 },
    { label: '自有车', value : 2 },
])

onMounted(() => {
    getTaskList();
})

const tips = ref<string | null>(null)
let map = null
const myMapRef = ref(null)
let circle = null
let circleEditor = null;
const initMap = (mapInstance) => {
    map = mapInstance;

};

const changeSearchType = () => {
    searchForm.carNumber = ''
    clearCircle();
}


const startDraw = () => {
    tips.value = '点击地图任意一点绘制';
    finalCircle.value = null;
    circleInfo.center = null;
    circleInfo.radius = null;
    map.clearMap();
    map.on('click', drawCircle);
    map.on('mousemove', drawTempCircle);
}



let circleCenter = null;      // 圆心坐标
let tempCircle = null;        // 临时圆形对象
let drawing = false;
const finalCircle = ref(null)

/**
 *
 * @param position [lng, lat]
 */
const drawCircle = (e) => {
    if (!drawing) {
        // 第一步：设置圆心
        circleCenter = e.lnglat;
        console.log(circleCenter)
        drawing = true;
        circleInfo.center = [circleCenter.lng, circleCenter.lat];
        tips.value = `圆心已设置，移动鼠标调整半径，再次点击完成`;
   // circleInfo.radius = params.radius;
        // document.getElementById('info').innerHTML =
        //     `圆心已设置：${circleCenter}<br>移动鼠标调整半径，再次点击完成`;
    } else {
        // 第二步：完成绘制

        drawing = false;
        if (tempCircle) {
            // 最终确定圆形
            tempCircle.setMap(null);

            circle =new AMap.Circle({
                center: circleCenter,
                radius: tempCircle.getRadius(), //半径
                borderWeight: 3,

                strokeOpacity: 1,
                strokeWeight: 6,
                strokeOpacity: 0.2,
                fillOpacity: 0.4,
                strokeStyle: 'dashed',
                strokeDasharray: [10, 10],
                // 线样式还支持 'dashed'
                fillColor: '#1791fc',
                zIndex: 50,
            })
            finalCircle.value = circle;
            circle.setMap(map);
            tempCircle = null;
        }
        circleCenter = null;
        tips.value = null

        map.off('click', drawCircle);
        map.off('mousemove', drawTempCircle);
    }

}

const drawTempCircle = e => {
    if (!drawing || !circleCenter) return;
    tips.value = `再次点击完成绘制`;
    // 计算圆心到鼠标位置的直线距离（米）
    const radius = Math.round(circleCenter.distance(e.lnglat));
    circleInfo.radius = radius;
    console.log(radius);
    // 移除旧圆
    if (tempCircle) {
        tempCircle.setMap(null);
    }

    // 绘制新圆
    tempCircle = new AMap.Circle({
        center: circleCenter,
        radius: radius,
        strokeColor: "#FF0000",
        strokeOpacity: 0.8,
        strokeWeight: 2,
        fillColor: "#FF6600",
        fillOpacity: 0.3,
        bubble: true

    });
    tempCircle.setMap(map);
}

const points = ref([])
const circleInfo = reactive({
    center: null,
    radius: null
})
// 获取圈内车辆
const getCircleMarker = async() => {
    const { lng, lat } = circle.getCenter();
    const radius = circle.getRadius();
    // TODO 接口替换，获取圈内车辆
    const params = {
        position: [lng, lat],
        carType: carType.value,   // 自有车还是全量车
        radius   // 半径，单位为米
    }
    // circleInfo.center = params.position;
    // circleInfo.radius = params.radius;
    points.value = await  getMarker(20, params.position, params.radius)
    drawMarkers(points.value);
}

// 在组件内部维护markers实例集合
let markers:[] = [];

/**
 * 绘制点位标记
 * @param points 二维坐标数组 [[lng, lat], [lng, lat]...]
 */
const blurIcon = 'https://a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-default.png'
const redIcon = 'https://a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-red.png'
const drawMarkers = (points: object[]) => {
    console.log(points)
  // 清除已有标记
    if (markers.length) {
        markers.forEach(marker => map.remove(marker));
        markers = [];
    }


    // 创建新标记
    points.forEach(point => {
        const marker = new AMap.Marker({
            position: [point.lng, point.lat], // 使用AMap内置坐标类
            map: map,
            icon: new AMap.Icon({
                image: blurIcon,
                size: new AMap.Size(25, 34),
                imageSize: new AMap.Size(25, 34),
            }), // 使用统一的图标
            offset: new AMap.Pixel(-13, -30), // 标注偏移量
            extData: point,
        });
        marker.setLabel({
            direction:'top',
            offset: new AMap.Pixel(10, 0),  //设置文本标注偏移量
            content: `<div class='info'>${point.carNumber}</div>`, //设置文本标注内容
        });
        marker.on('click', () => {
            handleMarkerClick(marker)
            combineTask(point)
        });

        markers.push(marker);
    });
    map.setFitView();

};
// 清除圆形和标记
const clearCircle = () => {
    // 清除圆形编辑器
    if (circleEditor) {
        circleEditor.close()
        circleEditor = null
    }
    points.value = [];
    // 移除圆形覆盖物
    if (circle) {
        map.remove(circle)
        circle = null
    }

    // 移除所有标记
    if (markers.length) {
        markers.forEach(marker => map.remove(marker))
        markers = []
    }
    drawing = false;
    tempCircle = null;
    circleCenter = null
    finalCircle.value = null;
    circleInfo.center = null;
    circleInfo.radius = null;
    circleInfo.center = null;
    circleInfo.radius = null



}
// 根据车牌号查询车辆
const handleOnsearch = async e => {
    // TODO  调用接口查询车辆信息,如果不存车辆则返回null
    const params = { carNumber: searchForm.carNumber }
    if(!searchForm.carNumber) {
        return ElMessage.error('请输入车牌号！')
    }
    const result = await searchMarker(params);

    if(result) {
        console.log(result)
        // 地图上是否已有该车辆
        points.value = [result]
        return drawMarkers(points.value)
    }
    return ElMessage.error('没有查询到该车辆！')
}

// 关联任务
const combineTask = async (point) => {
    if(!searchForm.task) {
        return  ElMessage.error('请选择任务');
    }
    try {
        await ElMessageBox.confirm(`是否将${point.carNumber}与任务${taskOpsList.value[searchForm.task].name}进行关联？`, '提示', {
            confirmButtonText: '确定',
            cancelButtonText: '取消',
            type: 'warning',
        })
        const params = {
            taskId: searchForm.task,   // 任务id
            carNumber: point.carNumber, // 车牌号
            carId: point.id, // 车辆id
        }
        // TODO  在此调用接口关联任务
        //  await combineTaskRequest(params)
            // 关联任务
        clearCircle()
        ElMessage.success('关联成功');
    } catch (error) {

        handleMarkerClick()
    }

}


const hightLightMarker = ref(null); // 用于存储高亮的 Marker
const handleMarkerClick = currentMarker => {
     // 清除所有高亮状态
    const currentMarkerId = currentMarker && currentMarker.getExtData().id;
    markers.forEach(marker => {
        const { id } = marker.getExtData();

        if(currentMarker &&　id === currentMarkerId) {
            const position = marker.getPosition();
            marker.setIcon(new AMap.Icon({
                image: redIcon,
                size: new AMap.Size(25, 34),
                imageSize: new AMap.Size(25, 34),
            })); // 设置高亮图标
            map.panTo(position,500); // 移动地图中心到车辆位置
        } else {

            marker.setIcon(new AMap.Icon({
                image: blurIcon,
                size: new AMap.Size(25, 34),
                imageSize: new AMap.Size(25, 34),
            })); // 恢复默认图标
        }
    });

}

// 点击列表某一行
const handleRowClick =  (row: any) => {
    const targetMarker = markers.find(item => {
        const extData = item.getExtData();
        return extData.carNumber === row.carNumber
    })
    handleMarkerClick(targetMarker);
    //combineTask(row);
}

const handleBindTask = (row: any) => {
   // handleRowClick(row)
    combineTask(row);
}




const searchFormRef = ref<FormInstance>(null);

const details = ref({});











</script>

